# subset GitHub Actions workflow files use: nested block mappings and block
# sequences (of scalars or mappings), plus quoted scalars. It exists so the
# workflow-structure Pester tests don't need the powershell-yaml module,
# which isn't installed in the act container (only pwsh + Pester are).

function Convert-ScalarYamlValue {
    [CmdletBinding()]
    [OutputType([object])]
    param(
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string]$Text
    )

    $trimmed = $Text.Trim()
    if ($trimmed.Length -ge 2 -and (
        ($trimmed.StartsWith("'") -and $trimmed.EndsWith("'")) -or
        ($trimmed.StartsWith('"') -and $trimmed.EndsWith('"'))
        )) {
        return $trimmed.Substring(1, $trimmed.Length - 2)
    }
    return $trimmed
}

function ConvertFrom-SimpleYaml {
    <#
    Parses an array of YAML lines (2-space indentation, no flow-style
    collections, no multi-line scalars) into nested [ordered] hashtables /
    arrays. Returns an [ordered] hashtable representing the document root.
    #>
    [CmdletBinding()]
    [OutputType([System.Collections.Specialized.OrderedDictionary])]
    param(
        # AllowEmptyString: Mandatory [string[]] params otherwise reject any
        # blank-line element, and blank lines are routine in YAML source.
        [Parameter(Mandatory)]
        [AllowEmptyString()]
        [string[]]$Lines
    )

    # Drop blank/full-line-comment lines up front but keep original indices
    # out of the picture entirely; only relative order matters.
    $meaningful = @()
    foreach ($line in $Lines) {
        if ($line.Trim() -eq '' -or $line.Trim().StartsWith('#')) { continue }
        $meaningful += $line
    }

    $root = [ordered]@{}
    # Stack of frames: each has Indent (int) and Node (the container at that indent).
    $stack = [System.Collections.Generic.List[object]]::new()
    $stack.Add(@{ Indent = -1; Node = $root })

    for ($i = 0; $i -lt $meaningful.Count; $i++) {
        $rawLine = $meaningful[$i]
        $indent = $rawLine.Length - $rawLine.TrimStart(' ').Length
        $line = $rawLine.Trim()

        while ($stack.Count -gt 1 -and $stack[$stack.Count - 1].Indent -ge $indent) {
            $stack.RemoveAt($stack.Count - 1)
        }
        $parent = $stack[$stack.Count - 1]

        if ($line.StartsWith('- ') -or $line -eq '-') {
            $itemText = if ($line -eq '-') { '' } else { $line.Substring(2) }
            if ($parent.Node -isnot [System.Collections.IList]) {
                throw "SimpleYaml parse error: sequence item found under a non-sequence key near '$line'"
            }

            if ($itemText -match '^([A-Za-z0-9_."''\-]+):\s*(.*)$') {
                # A '- key: value' item starts a mapping; the mapping's
                # effective indent is where the key text begins (2 past '-').
                $key = $matches[1].Trim('"''')
                $val = $matches[2]
                $itemMap = [ordered]@{}
                if ($val -eq '') {
                    $child = New-YamlPlaceholder -Lines $meaningful -FollowingIndex ($i + 1) -MinIndent ($indent + 2)
                    $itemMap[$key] = $child.Value
                }
                else {
                    $itemMap[$key] = Convert-ScalarYamlValue -Text $val
                }
                [void]$parent.Node.Add($itemMap)
                # Frame indent matches the '-' marker's own indent (mirroring
                # how regular mapping keys use their own line's indent) so a
                # sibling '- ...' item at the same indent correctly pops this
                # frame, while deeper-indented sibling keys (e.g. 'uses:'
                # under the same item) do not.
                $stack.Add(@{ Indent = $indent; Node = $itemMap })
            }
            else {
                [void]$parent.Node.Add((Convert-ScalarYamlValue -Text $itemText))
            }
            continue
        }

        if ($line -match '^([A-Za-z0-9_."''\-]+):\s*(.*)$') {
            $key = $matches[1].Trim('"''')
            $val = $matches[2]

            if ($val -eq '') {
                $child = New-YamlPlaceholder -Lines $meaningful -FollowingIndex ($i + 1) -MinIndent ($indent + 1)
                $parent.Node[$key] = $child.Value
                $stack.Add(@{ Indent = $indent; Node = $child.Value })
            }
            else {
                $parent.Node[$key] = Convert-ScalarYamlValue -Text $val
            }
            continue
        }

        throw "SimpleYaml parse error: could not parse line '$line'"
    }

    return $root
}

function New-YamlPlaceholder {
    # Looks at the next meaningful line to decide whether an empty-valued
    # key should become a nested mapping or a sequence; defaults to an
    # empty mapping when there is no deeper-indented content at all.
    [CmdletBinding()]
    param(
        [Parameter(Mandatory)]
        [string[]]$Lines,
        [Parameter(Mandatory)]
        [int]$FollowingIndex,
        [Parameter(Mandatory)]
        [int]$MinIndent
    )

    if ($FollowingIndex -lt $Lines.Count) {
        $next = $Lines[$FollowingIndex]
        $nextIndent = $next.Length - $next.TrimStart(' ').Length
        $nextTrimmed = $next.Trim()
        if ($nextIndent -ge $MinIndent -and ($nextTrimmed.StartsWith('- ') -or $nextTrimmed -eq '-')) {
            return @{ Value = [System.Collections.Generic.List[object]]::new() }
        }
    }
    return @{ Value = [ordered]@{} }
}

